const CACHE='nth-footprints-shell-v41';
const SHELL=['./','./index.html','./app.css','./app.js','./media-store.js','./journal-storage.js','./stream-archive.js','./journal-archive.js','./backup-parts.js','./rescue-legacy.js','./geography.js','./region-lookup.js','./categories.js','./place-source.js','./place-details.js','./discovery.js','./discovery-store.js','./places-config.js','./places-map.js','./places-ui.js','./model.js','./journal-tools.js','./journal-tools-ui.js','./batch-import.js','./batch-import-ui.js','./export-media.js','./exports-ui.js','./nearby-memories.js','./visits.js','./journeys.js','./journeys-ui.js','./deck.js','./geotags.js','./device.js','./drafts.js','./backup-file.js','./photo-export.js','./atlas.js','./visit-map.js','./offline-maps.js','./map-background.js','./location-tools.js','./place-search.js','./navigation.js','./releases.js','./widget.js','./gallery.js','./photo-preview.js','./photo-lightbox.js','./pin-previews.js','./vendor/leaflet/leaflet.js','./vendor/leaflet/leaflet.css','./manifest.webmanifest','./assets/icon.svg','./assets/icon-192.png','./assets/icon-512.png','./assets/icon-maskable-192.png','./assets/icon-maskable-512.png','./assets/favicon-32.png','./assets/apple-touch-icon.png','./assets/coast.svg','./assets/mountain.svg','./assets/city.svg','./assets/blank.svg'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)));});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('nth-footprints-shell-')&&k!==CACHE).map(k=>caches.delete(k)))));});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;const url=new URL(e.request.url);if(!SHELL.some(p=>new URL(p,self.registration.scope).pathname===url.pathname))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request).then(r=>r||caches.match('./index.html'))));});
